import { MigrateUpArgs, MigrateDownArgs, sql } from '@payloadcms/db-postgres'
import { enableRlsOnPayloadTables } from '../db/enable-rls'

// M3-07: slug history for the 308 of old publication URLs (DECISIONS §2.11
// P9 A; collection publication-slugs, DATA-MODEL §4 PublicationSlug).
// Additive only: one enum, one table, one nullable column on
// payload_locked_documents_rels. Generated by `payload migrate:create`;
// added by hand: the backfill and enableRlsOnPayloadTables.
//
// Backfill: every URL visitors could open before this migration. First the
// live published + public records (a live slug points to its record), then
// the published + public versions, newest per (locale, slug), so a slug that
// two records published belongs to the later one. A version of a deleted
// record (parent gone) is skipped. ON CONFLICT keeps the live rows.
export async function up({ db, payload, req }: MigrateUpArgs): Promise<void> {
  await db.execute(sql`
   CREATE TYPE "public"."enum_publication_slugs_locale" AS ENUM('id', 'en');
  CREATE TABLE "publication_slugs" (
  	"id" serial PRIMARY KEY NOT NULL,
  	"publication_id" integer NOT NULL,
  	"locale" "enum_publication_slugs_locale" NOT NULL,
  	"slug" varchar NOT NULL,
  	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
  	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL
  );
  
  ALTER TABLE "payload_locked_documents_rels" ADD COLUMN "publication_slugs_id" integer;
  ALTER TABLE "publication_slugs" ADD CONSTRAINT "publication_slugs_publication_id_publications_id_fk" FOREIGN KEY ("publication_id") REFERENCES "public"."publications"("id") ON DELETE set null ON UPDATE no action;
  CREATE INDEX "publication_slugs_publication_idx" ON "publication_slugs" USING btree ("publication_id");
  CREATE INDEX "publication_slugs_updated_at_idx" ON "publication_slugs" USING btree ("updated_at");
  CREATE INDEX "publication_slugs_created_at_idx" ON "publication_slugs" USING btree ("created_at");
  CREATE UNIQUE INDEX "locale_slug_1_idx" ON "publication_slugs" USING btree ("locale","slug");
  ALTER TABLE "payload_locked_documents_rels" ADD CONSTRAINT "payload_locked_documents_rels_publication_slugs_fk" FOREIGN KEY ("publication_slugs_id") REFERENCES "public"."publication_slugs"("id") ON DELETE cascade ON UPDATE no action;
  CREATE INDEX "payload_locked_documents_rels_publication_slugs_id_idx" ON "payload_locked_documents_rels" USING btree ("publication_slugs_id");`)

  await db.execute(sql`
   INSERT INTO "publication_slugs" ("publication_id", "locale", "slug")
  SELECT p."id", p."locale"::text::"enum_publication_slugs_locale", p."slug"
    FROM "publications" p
   WHERE p."_status" = 'published' AND p."access_level" = 'public'
     AND p."locale" IS NOT NULL AND p."slug" IS NOT NULL
  ON CONFLICT ("locale", "slug") DO NOTHING;
  INSERT INTO "publication_slugs" ("publication_id", "locale", "slug")
  SELECT DISTINCT ON (v."version_locale", v."version_slug")
         v."parent_id", v."version_locale"::text::"enum_publication_slugs_locale", v."version_slug"
    FROM "_publications_v" v
    JOIN "publications" p ON p."id" = v."parent_id"
   WHERE v."version__status" = 'published' AND v."version_access_level" = 'public'
     AND v."version_locale" IS NOT NULL AND v."version_slug" IS NOT NULL
   ORDER BY v."version_locale", v."version_slug", v."created_at" DESC, v."id" DESC
  ON CONFLICT ("locale", "slug") DO NOTHING;`)

  await enableRlsOnPayloadTables({ db, payload, req })
}

// Drops the slug history (the rows are lost; running up() again rebuilds
// them from the live records and the versions that are still kept). The
// locked-documents column goes first, it holds the only foreign key to the
// table. IF EXISTS guards keep it order-independent, same pattern as
// 20261109_132023_publications.
export async function down({ db }: MigrateDownArgs): Promise<void> {
  await db.execute(sql`
   ALTER TABLE IF EXISTS "payload_locked_documents_rels" DROP CONSTRAINT IF EXISTS "payload_locked_documents_rels_publication_slugs_fk";
  DROP INDEX IF EXISTS "payload_locked_documents_rels_publication_slugs_id_idx";
  ALTER TABLE IF EXISTS "payload_locked_documents_rels" DROP COLUMN IF EXISTS "publication_slugs_id";
  ALTER TABLE IF EXISTS "publication_slugs" DISABLE ROW LEVEL SECURITY;
  DROP TABLE IF EXISTS "publication_slugs" CASCADE;
  DROP TYPE IF EXISTS "public"."enum_publication_slugs_locale";`)
}
